BEGIN TRANSACTION;
CREATE TABLE agents(id TEXT PRIMARY KEY, name TEXT, capability TEXT, status TEXT);
CREATE TABLE agreement(metric TEXT, value TEXT, agents TEXT, sources TEXT);
CREATE TABLE artifacts(id TEXT PRIMARY KEY, drive_id TEXT, name TEXT, author TEXT, read_in_full INT);
CREATE TABLE experts(id TEXT PRIMARY KEY, name TEXT, scope TEXT);
CREATE TABLE findings(id TEXT PRIMARY KEY, title TEXT, severity INT, evidence INT, reach INT,
          energy INT, route TEXT, expert TEXT REFERENCES experts(id), owner TEXT, evidence_note TEXT,
          sources TEXT, next_step TEXT, status TEXT DEFAULT 'OPEN');
CREATE TABLE gates(id TEXT PRIMARY KEY, criterion TEXT, status TEXT, sources TEXT);
CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE workflow_steps(id TEXT PRIMARY KEY, title TEXT, executor TEXT, reviewer TEXT, output TEXT,
          token_in_k REAL, token_out_k REAL, gate TEXT, depends_on TEXT, lane TEXT, status TEXT DEFAULT 'NOT_RUN');
CREATE VIEW v_signal_energy AS SELECT id, energy, route, expert, owner, next_step, title
          FROM findings ORDER BY energy DESC, id;
COMMIT;
